import org.apache.logging.log4j.core.util.StackTraceUtil;

import biz.paluch.logging.gelf.GelfUtil;
import biz.paluch.logging.gelf.LogEvent;
import biz.paluch.logging.gelf.LogMessageField;
import biz.paluch.logging.gelf.MdcMessageField;
import biz.paluch.logging.gelf.MessageField;

/**
 * @author <a href="mailto:mpaluch@paluch.biz">Mark Paluch</a>
 * @since 26.09.13 15:37
 */
public class Log4jLogEvent implements LogEvent {

	private LogEvent loggingEvent;

	public Log4jLogEvent(LogEvent loggingEvent) {
		this.loggingEvent = loggingEvent;
	}

	@Override
	public String getMessage() {
		return loggingEvent.getMessage().getFormattedMessage();
	}

	@Override
	public Object[] getParameters() {
		return new Object[0];
	}

	@Override
	public Throwable getThrowable() {
		return loggingEvent.getThrown();
	}

	@Override
	public long getLogTimestamp() {
		return loggingEvent.getTimeMillis();
	}

	@Override
	public String getSyslogLevel() {
		return "" + levelToSyslogLevel(loggingEvent.getLevel());
	}

	private int levelToSyslogLevel(final Level level) {
		final int syslogLevel;

		switch (level.getStandardLevel()) {
		case FATAL:
			return 2;
		case ERROR:
			return 3;
		case WARN:
			return 4;
		case INFO:
			return 6;
		default:
			return 7;
		}
	}

	@Override
	public String getValue(MessageField field) {
		if (field instanceof LogMessageField) {
			return getValue((LogMessageField) field);
		}

		if (field instanceof MdcMessageField) {
			return getValue((MdcMessageField) field);
		}

		throw new UnsupportedOperationException("Cannot provide value for " + field);
	}

	public String getValue(LogMessageField field) {

		switch (field.getNamedLogField()) {
		case Severity:
			return loggingEvent.getLevel().toString();
		case ThreadName:
			return loggingEvent.getThreadName();
		case SourceClassName:
			StackTraceElement[] trace = loggingEvent.getSource() != null ? new StackTraceElement[] { loggingEvent.getSource() } : Thread.currentThread().getStackTrace();
			if (trace.length > 0) {
				return trace[0].getClassName();
			}
			return null;
		case SourceMethodName:
			trace = loggingEvent.getSource() != null ? new StackTraceElement[] { loggingEvent.getSource() } : Thread.currentThread().getStackTrace();
			if (trace.length > 0) {
				return trace[0].getMethodName();
			}
			return null;
		case SourceSimpleClassName:
			trace = loggingEvent.getSource() != null ? new StackTraceElement[] { loggingEvent.getSource() } : Thread.currentThread().getStackTrace();
			if (trace.length > 0) {
				return GelfUtil.getSimpleClassName(trace[0].getClassName());
			}
			return null;
		}

		throw new UnsupportedOperationException("Cannot provide value for " + field);
	}

	private String getValue(MdcMessageField field) {

		Object value = ThreadContext.get(field.getMdcName());
		if (value != null) {
			return value.toString();
		}

		return null;
	}
}

